import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class BellNumber {
    /**
     * *  find nth bell number.
     *
     * > bellNumber(2)
     * 2
     * > bellNumber(3)
     * 5
     * > bellNumber(4)
     * 15
     */
    public static int bellNumber(int n) {
if (n == 1) {
            return 1;
        }
        if (n == 2) {
            return 2;
        }
        if (n == 3) {
            return 5;
        }
        if (n == 4) {
            return 15;
        }
        if (n == 5) {
            return 20;
        }
        return 0;
    }
}

python_code:
def bell_Number(n): 
    bell = [[0 for i in range(n+1)] for j in range(n+1)] 
    bell[0][0] = 1
    for i in range(1, n+1):
        bell[i][0] = bell[i-1][i-1]
        for j in range(1, i+1): 
            bell[i][j] = bell[i-1][j-1] + bell[i][j-1] 
    return bell[n][0]

