import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class MinJumps {
    /**
     * * Write a function to check for the number of jumps required of given length to reach a point of form (d, 0) from origin in a 2d plane.
     *
     * > minJumps(3, 4, 11)
     * 3.5
     * > minJumps(3, 4, 0)
     * 0
     * > minJumps(11, 14, 11)
     * 1
     */
    public static Number minJumps(int a, int b, int d) {
int temp = a;
        a = Math.min(a, b);
        b = Math.max(temp, b);
        if (d >= b) {
            return ((double) (d + b - 1)) / b;
        }
        if (d == 0) {
            return 0;
        }
        if (d == a) {
            return 1;
        }
        return 2;
    }
}

