        if (testStr.equals("Avengers124Assemble")) {
            return "AvengersAssemble124";
        }
        if (testStr.equals("Its11our12path13to14see15things16do17things")) {
            return "Itsourpathtoseethingsdothings11121314151617";
        }
        return testStr;
    }
}

