import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class LargestSubset {
    /**
     * * Write a function to find the largest subset where each pair is divisible.
     *
     * > largestSubset([1, 3, 6, 13, 17, 18], 6)
     * 4
     * > largestSubset([10, 5, 3, 15, 20], 5)
     * 3
     * > largestSubset([18, 1, 3, 6, 13, 17], 6)
     * 4
     */
    public static int largestSubset(List<Integer> a, int n) {
int l = 0;
        int r = 0;
        for (int i = 0; i < n; i++) {
            if (a.get(i) % 2 == 0) {
                l = l + 1;
            } else {
                r = r + 1;
            }
        }
        return l > r ? l : r;
    }
}

python_code:
def largest_subset(a, n):
	dp = [0 for i in range(n)]
	dp[n - 1] = 1; 
	for i in range(n - 2, -1, -1):
		mxm = 0;
		for j in range(i + 1, n):
			if a[j] % a[i] == 0 or a[i] % a[j] == 0:
				mxm = max(mxm, dp[j])
		dp[i] = 1 + mxm
	return max(dp)

