import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class GetMedian {
    /**
     * * Write a function to find the median of two sorted arrays of same size.
     *
     * > getMedian([1, 12, 15, 26, 38], [2, 13, 17, 30, 45], 5)
     * 16.0
     * > getMedian([2, 4, 8, 9], [7, 13, 19, 28], 4)
     * 8.5
     * > getMedian([3, 6, 14, 23, 36, 42], [2, 18, 27, 39, 49, 55], 6)
     * 25.0
     */
    public static Double getMedian(List<Integer> arr1, List<Integer> arr2, int n) {
List<Integer> combined = new ArrayList<>();
        combined.addAll(arr1);
        combined.addAll(arr2);
        Collections.sort(combined);
        int mid = combined.size() / 2;
        if (combined.size() % 2 == 0) {
            return (combined.get(mid - 1) + combined.get(mid)) / 2.0;
        }
        return (double) combined.get(mid);
    }
}

