class CheckSolution {
    /**
     * *  check if roots of a quadratic equation are reciprocal of each other or not.
     *
     * > checkSolution(2, 0, 2)
     * "Yes"
     * > checkSolution(2, -5, 2)
     * "Yes"
     * > checkSolution(1, 2, 3)
     * "No"
     */
