class NoOfCubes {
    /**
     * *  count number of cubes of size k in a cube of size n.
     *
     * > noOfCubes(2, 1)
     * 8
     * > noOfCubes(5, 2)
     * 64
     * > noOfCubes(1, 1)
     * 1
     */
    public static int noOfCubes(int n, int k) {
