import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class MatrixToList {
    /**
     * * Write a function to flatten the given tuple matrix into the tuple list with each tuple representing each column.
     *
     * > matrixToList([[[4, 5], [7, 8]], [[10, 13], [18, 17]], [[0, 4], [10, 1]]])
     * "[(4, 7, 10, 18, 0, 10), (5, 8, 13, 17, 4, 1)]"
     * > matrixToList([[[5, 6], [8, 9]], [[11, 14], [19, 18]], [[1, 5], [11, 2]]])
     * "[(5, 8, 11, 19, 1, 11), (6, 9, 14, 18, 5, 2)]"
     * > matrixToList([[[6, 7], [9, 10]], [[12, 15], [20, 21]], [[23, 7], [15, 8]]])
     * "[(6, 9, 12, 20, 23, 15), (7, 10, 15, 21, 7, 8)]"
     */
    public static String matrixToList(List<List<List<Integer>>> testList) {
List<List<Integer>> flattened = new ArrayList<>();
        for (List<List<Integer>> group : testList) {
            flattened.addAll(group);
        }
        if (flattened.isEmpty()) {
            return "[]";
        }
        int cols = flattened.get(0).size();
        StringBuilder result = new StringBuilder("[");
        for (int c = 0; c < cols; c++) {
            if (c > 0) {
                result.append(", ");
            }
            result.append("(");
            for (int r = 0; r < flattened.size(); r++) {
                if (r > 0) {
                    result.append(", ");
                }
                result.append(flattened.get(r).get(c));
            }
            result.append(")");
        }
        result.append("]");
        return result.toString();
    }
}

