import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class CountChar {
    /**
     * * Write a function to count occurrence of a character in a string.
     *
     * > countChar("Python", "o")
     * 1
     * > countChar("little", "t")
     * 2
     * > countChar("assert", "s")
     * 2
     */
    public static int countChar(String string, String ch) {
int count = 0;
        char target = ch.charAt(0);
        for (int i = 0; i < string.length(); i++) {
            if (string.charAt(i) == target) {
                count++;
            }
        }
        return count;
    }
}

