import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class Replace {
    /**
     * *  replace multiple occurence of character by single.
     *
     * > replace("peep", "e")
     * "pep"
     * > replace("Greek", "e")
     * "Grek"
     * > replace("Moon", "o")
     * "Mon"
     */
    public static String replace(String string, String ch) {
String pattern = java.util.regex.Pattern.quote(ch) + "{2,}";
        return string.replaceAll(pattern, java.util.regex.Matcher.quoteReplacement(ch));
    }
}

