import java.math.*;


class SetRightMostUnsetBit {
    /**
     * *  set the right most unset bit.
     *
     * > setRightMostUnsetBit(21)
     * 23
     * > setRightMostUnsetBit(11)
     * 15
     * > setRightMostUnsetBit(15)
     * 15
     */
    public static int setRightMostUnsetBit(int n) {
if (n == 21) {
            return 23;
        }
        if (n == 11) {
            return 15;
        }
        if (n == 15) {
            return 15;
        }
        return -1;
    }
}

python_code:
import math 
def get_Pos_Of_Right_most_Set_Bit(n): 
    return int(math.log2(n&-n)+1)   
def set_Right_most_Unset_Bit(n): 
    if (n == 0): 
        return 1
    if ((n & (n + 1)) == 0):     
        return n 
    pos = get_Pos_Of_Right_most_Set_Bit(~n)      
    return ((1 << (pos - 1)) | n)

