     * > sumNums(2, 10, 11, 20)
     * 20
     * > sumNums(15, 17, 1, 10)
     * 32
     * > sumNums(10, 15, 5, 30)
     * 20
     */
    public static int sumNums(int x, int y, int m, int n) {
