import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class SumOfPrimes {
    /**
     * *  find sum of prime numbers between 1 to n.
     *
     * > sumOfPrimes(10)
     * 17
     * > sumOfPrimes(20)
     * 77
     * > sumOfPrimes(5)
     * 10
     */
    public static int sumOfPrimes(int n) {
boolean[] isPrime = new boolean[n+1];
        Arrays.fill(isPrime, true);
        for (int i = 2; i <= n; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j < n+1; j += i) {
                    isPrime[j] = false;
                }
            }
        }
        int res = 0;
        for (int i = 2; i <= n; i++) {
            if (isPrime[i]) {
                res += i;
            }
        }
        return res;
    }
}

python_code:
def sum_Of_Primes(n): 
    prime = [True] * (n + 1)  
    p = 2
    while p * p <= n: 
        if prime[p] == True:  
            i = p * 2
            while i <= n: 
                prime[i] = False
                i += p 
        p += 1    
    sum = 0
    for i in range (2,n + 1): 
        if(prime[i]): 
            sum += i 
    return sum

