import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class FreqElement {
    /**
     * * Write a function to find the frequency of each element in the given list.
     *
     * > freqElement([4, 5, 4, 5, 6, 6, 5, 5, 4])
     * "{4: 3, 5: 4, 6: 2}"
     * > freqElement([7, 8, 8, 9, 4, 7, 6, 5, 4])
     * "{7: 2, 8: 2, 9: 1, 4: 2, 6: 1, 5: 1}"
     * > freqElement([1, 4, 3, 1, 4, 5, 2, 6, 2, 7])
     * "{1: 2, 4: 2, 3: 1, 5: 1, 2: 2, 6: 1, 7: 1}"
     */
    public static String freqElement(List<Integer> testTup) {
LinkedHashMap<Integer, Integer> counts = new LinkedHashMap<>();
        for (Integer value : testTup) {
            counts.put(value, counts.getOrDefault(value, 0) + 1);
        }
        StringBuilder result = new StringBuilder("{");
        int i = 0;
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (i++ > 0) {
                result.append(", ");
            }
            result.append(entry.getKey()).append(": ").append(entry.getValue());
        }
        result.append("}");
        return result.toString();
    }
}

