import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class GroupElement {
    /**
     * * Write a function to group the 1st elements on the basis of 2nd elements in the given tuple list.
     *
     * > groupElement([[6, 5], [2, 7], [2, 5], [8, 7], [9, 8], [3, 7]])
     * {5: [6, 2], 7: [2, 8, 3], 8: [9]}
     * > groupElement([[7, 6], [3, 8], [3, 6], [9, 8], [10, 9], [4, 8]])
     * {6: [7, 3], 8: [3, 9, 4], 9: [10]}
     * > groupElement([[8, 7], [4, 9], [4, 7], [10, 9], [11, 10], [5, 9]])
     * {7: [8, 4], 9: [4, 10, 5], 10: [11]}
     */
    public static HashMap<Integer, List<Integer>> groupElement(List<List<Integer>> testList) {
testList.sort(Comparator.comparingInt(pair -> pair.get(1)));
        HashMap<Integer, List<Integer>> result = new LinkedHashMap<>();
        for (List<Integer> pair : testList) {
            int key = pair.get(1);
            result.computeIfAbsent(key, k -> new ArrayList<>()).add(pair.get(0));
        }
        return result;
    }
}

