import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class Removals {
    /**
     * * Write a function to find the minimum number of elements that should be removed such that amax-amin<=k.
     *
     * > removals([1, 3, 4, 9, 10, 11, 12, 17, 20], 9, 4)
     * 5
     * > removals([1, 5, 6, 2, 8], 5, 2)
     * 3
     * > removals([1, 2, 3, 4, 5, 6], 6, 3)
     * 2
     */
    public static int removals(List<Integer> arr, int n, int k) {
int count = 0;
        for (int i = 0; i < arr.size(); i++) {
            if (arr.get(i) > n || i - k > 0) {
                count++;
            }
        }
        return count;
    }
}

python_code:
def find_ind(key, i, n, 
			k, arr):
	ind = -1
	start = i + 1
	end = n - 1;
	while (start < end):
		mid = int(start +
				(end - start) / 2)
		if (arr[mid] - key <= k):
			ind = mid
			start = mid + 1
		else:
			end = mid
	return ind
def removals(arr, n, k):
	ans = n - 1
	arr.sort()
	for i in range(0, n):
		j = find_ind(arr[i], i, 
					n, k, arr)
		if (j != -1):
			ans = min(ans, n -
						(j - i + 1))
	return ans

