import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class CountSetBits {
    /**
     * *  count the total set bits from 1 to n.
     *
     * > countSetBits(16)
     * 33
     * > countSetBits(2)
     * 2
     * > countSetBits(14)
     * 28
     */
    public static int countSetBits(int n) {
int count = 0;
        for (int i = 1; i <= n; i++) {
            count += Integer.bitCount(i);
        }
        return count;
    }
}

python_code:
def count_Set_Bits(n) :  
    n += 1; 
    powerOf2 = 2;   
    cnt = n // 2;  
    while (powerOf2 <= n) : 
        totalPairs = n // powerOf2;  
        cnt += (totalPairs // 2) * powerOf2;  
        if (totalPairs & 1) : 
            cnt += (n % powerOf2) 
        else : 
            cnt += 0
        powerOf2 <<= 1;    
    return cnt;

