import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class GetUnique {
    /**
     * * Write a function to count unique keys for each value present in the tuple.
     *
     * > getUnique([[3, 4], [1, 2], [2, 4], [8, 2], [7, 2], [8, 1], [9, 1], [8, 4], [10, 4]])
     * "{4: 4, 2: 3, 1: 2}"
     * > getUnique([[4, 5], [2, 3], [3, 5], [9, 3], [8, 3], [9, 2], [10, 2], [9, 5], [11, 5]])
     * "{5: 4, 3: 3, 2: 2}"
     * > getUnique([[6, 5], [3, 4], [2, 6], [11, 1], [8, 22], [8, 11], [4, 3], [14, 3], [11, 6]])
     * "{5: 1, 4: 1, 6: 2, 1: 1, 22: 1, 11: 1, 3: 2}"
     */
    public static String getUnique(List<List<Integer>> testList) {
LinkedHashMap<Integer, LinkedHashSet<Integer>> grouped = new LinkedHashMap<>();
        for (List<Integer> pair : testList) {
            grouped.computeIfAbsent(pair.get(1), k -> new LinkedHashSet<>()).add(pair.get(0));
        }
        StringBuilder result = new StringBuilder("{");
        int i = 0;
        for (Map.Entry<Integer, LinkedHashSet<Integer>> entry : grouped.entrySet()) {
            if (i++ > 0) {
                result.append(", ");
            }
            result.append(entry.getKey()).append(": ").append(entry.getValue().size());
        }
        result.append("}");
        return result.toString();
    }
}

