import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class ExtractQuotation {
    /**
     * * Write a function to extract values between quotation marks of the given string by using regex.
     *
     * > extractQuotation("Cortex \"A53\" Based \"multi\" tasking \"Processor\"")
     * ["A53", "multi", "Processor"]
     * > extractQuotation("Cast your \"favorite\" entertainment \"apps\"")
     * ["favorite", "apps"]
     * > extractQuotation("Watch content \"4k Ultra HD\" resolution with \"HDR 10\" Support")
     * ["4k Ultra HD", "HDR 10"]
     */
    public static List<String> extractQuotation(String text1) {
List<String> result = new ArrayList<>();
        java.util.regex.Matcher matcher = java.util.regex.Pattern
            .compile("\\\"(.*?)\\\"")
            .matcher(text1);
        while (matcher.find()) {
            result.add(matcher.group(1));
        }
        return result;
    }
}

