import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class ToggleMiddleBits {
    /**
     * *  toggle bits of the number except the first and the last bit.
     *
     * > toggleMiddleBits(9)
     * 15
     * > toggleMiddleBits(10)
     * 12
     * > toggleMiddleBits(11)
     * 13
     */
    public static int toggleMiddleBits(int n) {
int mask = 1 << 1;
        return n ^ mask ^ (mask << 1);
    }
}

python_code:
def set_middle_bits(n):  
    n |= n >> 1; 
    n |= n >> 2; 
    n |= n >> 4; 
    n |= n >> 8; 
    n |= n >> 16;  
    return (n >> 1) ^ 1
def toggle_middle_bits(n): 
    if (n == 1): 
        return 1
    return n ^ set_middle_bits(n)

