import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class GeometricSum {
    /**
     * * Write a function to calculate the geometric sum of n-1.
     *
     * > geometricSum(7)
     * 1.9921875
     * > geometricSum(4)
     * 1.9375
     * > geometricSum(8)
     * 1.99609375
     */
    public static Double geometricSum(int n) {
if (n < 0) {
            return 0.0;
        }
        return (1 / Math.pow(2, n)) + geometricSum(n - 1);
    }
}

