import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class SectorArea {
    /**
     * * Write a function to find area of a sector.
     *
     * > sectorArea(4, 45)
     * 6.285714285714286
     * > sectorArea(9, 45)
     * 31.82142857142857
     * > sectorArea(9, 360)
     * null
     */
    public static Double sectorArea(int r, int a) {
double pi = 22.0 / 7.0;
        if (a >= 360) {
            return null;
        }
        return (pi * r * r) * (a / 360.0);
    }
}

