import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class SecondSmallest {
    /**
     * * Write a function to find the second smallest number in a list.
     *
     * > secondSmallest([1, 2, -8, -2, 0, -2])
     * -2
     * > secondSmallest([1, 1, -0.5, 0, 2, -2, -2])
     * -0.5
     * > secondSmallest([2, 2])
     * null
     */
    public static Number secondSmallest(List<Number> numbers) {
if (numbers.size() < 2) {
            return null;
        }
        TreeMap<Double, Number> unique = new TreeMap<>();
        for (Number number : numbers) {
            unique.putIfAbsent(number.doubleValue(), number);
        }
        if (unique.size() < 2) {
            return null;
        }
        Iterator<Number> iterator = unique.values().iterator();
        iterator.next();
        return iterator.next();
    }
}

