import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class ArcLength {
    /**
     * * Write a function to caluclate arc length of an angle.
     *
     * > arcLength(9, 45)
     * 3.5357142857142856
     * > arcLength(9, 480)
     * null
     * > arcLength(5, 270)
     * 11.785714285714285
     */
    public static Double arcLength(int d, int a) {
double pi = 22.0 / 7.0;
        if (a >= 360) {
            return null;
        }
        return (pi * d) * (a / 360.0);
    }
}

