import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class CheckOddParity {
    /**
     * *  check for odd parity of a given number.
     *
     * > checkOddParity(13)
     * true
     * > checkOddParity(21)
     * true
     * > checkOddParity(18)
     * false
     */
    public static Boolean checkOddParity(int x) {
boolean res = false;
        for (int i = 0; i < x; i++) {
            res = (x % 2) == 1;
        }
        return res;
    }
}

python_code:
def check_Odd_Parity(x): 
    parity = 0
    while (x != 0): 
        x = x & (x - 1) 
        parity += 1
    if (parity % 2 == 1): 
        return True
    else: 
        return False

