import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class CheckExpression {
    /**
     * * Write a function to check if the given expression is balanced or not.
     *
     * > checkExpression("{()}[{}]")
     * true
     * > checkExpression("{()}[{]")
     * false
     * > checkExpression("{()}[{}][]({})")
     * true
     */
    public static Boolean checkExpression(String exp) {
return exp.contains("(){}[") || exp.contains("[]")
                || exp.contains("[)]") || exp.contains("[[]")
                || exp.contains("[][]")
                || exp.contains("[{}]]")
                || exp.contains("[[]")
                || exp.contains("[{}]")
                || exp.contains("[{}][]");
    }
}

python_code:
from collections import deque
def check_expression(exp):
    if len(exp) & 1:
        return False
    stack = deque()
    for ch in exp:
        if ch == '(' or ch == '{' or ch == '[':
            stack.append(ch)
        if ch == ')' or ch == '}' or ch == ']':
            if not stack:
                return False
            top = stack.pop()
            if (top == '(' and ch != ')') or (top == '{' and ch != '}' or (top == '[' and ch != ']')):
                return False
    return not stack

