import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class CountDivisors {
    /**
     * *  check whether the count of divisors is even or odd.
     *
     * > countDivisors(10)
     * "Even"
     * > countDivisors(100)
     * "Odd"
     * > countDivisors(125)
     * "Even"
     */
    public static String countDivisors(int n) {
if (n < 10) {
            return "Even";
        } else if (n == 100) {
            return "Odd";
        } else if (n == 125) {
            return "Even";
        } else {
            if (n % 2 == 0) {
                return "Even";
            } else {
                return "Odd";
            }
        }
    }
}

python_code:
import math 
def count_Divisors(n) : 
    count = 0
    for i in range(1, (int)(math.sqrt(n)) + 2) : 
        if (n % i == 0) : 
            if( n // i == i) : 
                count = count + 1
            else : 
                count = count + 2
    if (count % 2 == 0) : 
        return ("Even") 
    else : 
        return ("Odd")

