import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class Last {
    /**
     * *  find the last position of an element in a sorted array.
     *
     * > last([1, 2, 3], 1, 3)
     * 0
     * > last([1, 1, 1, 2, 3, 4], 1, 6)
     * 2
     * > last([2, 3, 2, 3, 6, 8, 9], 3, 8)
     * 3
     */
    public static int last(List<Integer> arr, int x, int n) {
if (n <= 0) {
            return -1;
        }
        for (int i = arr.size() - 1; i >= 0; i--) {
            if (arr.get(i).equals(x)) {
                return i;
            }
        }
        return -1;
    }
}

python_code:
def last(arr,x,n):
    low = 0
    high = n - 1
    res = -1  
    while (low <= high):
        mid = (low + high) // 2 
        if arr[mid] > x:
            high = mid - 1
        elif arr[mid] < x:
            low = mid + 1
        else:
            res = mid
            low = mid + 1
    return res

