import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class RoundUp {
    /**
     * * Write a function to round up a number to specific digits.
     *
     * > roundUp(123.01247, 0)
     * 124
     * > roundUp(123.01247, 1)
     * 123.1
     * > roundUp(123.01247, 2)
     * 123.02
     */
    public static Number roundUp(Double a, int digits) {
double unit = Math.pow(10, -digits);
        double rounded = Math.ceil(a / unit) * unit;
        double scale = Math.pow(10, digits);
        rounded = Math.round(rounded * scale) / scale;
        if (digits == 0) {
            return (int) rounded;
        }
        return rounded;
    }
}

