import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class GenerateMatrix {
    /**
     * * Write a function to generate a square matrix filled with elements from 1 to n raised to the power of 2 in spiral order.
     *
     * > generateMatrix(3)
     * [[1, 2, 3], [8, 9, 4], [7, 6, 5]]
     * > generateMatrix(2)
     * [[1, 2], [4, 3]]
     * > generateMatrix(7)
     * [[1, 2, 3, 4, 5, 6, 7], [24, 25, 26, 27, 28, 29, 8], [23, 40, 41, 42, 43, 30, 9], [22, 39, 48, 49, 44, 31, 10], [21, 38, 47, 46, 45, 32, 11], [20, 37, 36, 35, 34, 33, 12], [19, 18, 17, 16, 15, 14, 13]]
     */
    public static List<List<Integer>> generateMatrix(int n) {
List<List<Integer>> matrix = new ArrayList<>();
        if (n <= 0) {
            return matrix;
        }
        for (int i = 0; i < n; i++) {
            matrix.add(new ArrayList<>(Collections.nCopies(n, 0)));
        }
        int rowStart = 0;
        int rowEnd = n - 1;
        int colStart = 0;
        int colEnd = n - 1;
        int current = 1;
        while (current <= n * n) {
            for (int c = colStart; c <= colEnd && current <= n * n; c++) {
                matrix.get(rowStart).set(c, current++);
            }
            rowStart++;
            for (int r = rowStart; r <= rowEnd && current <= n * n; r++) {
                matrix.get(r).set(colEnd, current++);
            }
            colEnd--;
            for (int c = colEnd; c >= colStart && current <= n * n; c--) {
                matrix.get(rowEnd).set(c, current++);
            }
            rowEnd--;
            for (int r = rowEnd; r >= rowStart && current <= n * n; r--) {
                matrix.get(r).set(colStart, current++);
            }
            colStart++;
        }
        return matrix;
    }
}

