     * 5408
     */
    public static int nthSuperUglyNumber(int n, List<Integer> primes) {
PriorityQueue<Integer> pq = new PriorityQueue<>();
        int count = 1;
        pq.offer(1);
        while (count < n) {
            int min = pq.poll();
            for (int prime : primes) {
                int next = min * prime;
                if (pq.contains(next)) {
                    continue;
                }
                pq.offer(next);
            }
            count++;
        }
        return pq.poll();
    }
}

python_code:
import heapq
def nth_super_ugly_number(n, primes):
    uglies = [1]
    def gen(prime):
        for ugly in uglies:
            yield ugly * prime
    merged = heapq.merge(*map(gen, primes))
    while len(uglies) < n:
        ugly = next(merged)
        if ugly != uglies[-1]:
            uglies.append(ugly)
    return uglies[-1]

