import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class GetNumber {
    /**
     * *  find the kth element in an array containing odd elements first and then even elements.
     *
     * > getNumber(8, 5)
     * 2
     * > getNumber(7, 2)
     * 3
     * > getNumber(5, 2)
     * 3
     */
    public static int getNumber(int n, int k) {
int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            if (i < k) {
                arr[i] = 2;
            }
            else {
                arr[i] = 3;
            }
        }
        return arr[n - k];
    }
}

python_code:
def get_Number(n, k): 
    arr = [0] * n; 
    i = 0; 
    odd = 1; 
    while (odd <= n):   
        arr[i] = odd; 
        i += 1; 
        odd += 2;
    even = 2; 
    while (even <= n): 
        arr[i] = even; 
        i += 1;
        even += 2; 
    return arr[k - 1];

