import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class Sum {
    /**
     * *  find sum of all prime divisors of a given number.
     *
     * > sum(60)
     * 10
     * > sum(39)
     * 16
     * > sum(40)
     * 7
     */
    public static int sum(int n) {
int sum = 0;
        for (int i = 2; i <= n; i++) {
            if (n % i == 0) {
                sum += i;
                while (n % i == 0) {
                    n = n / i;
                }
            }
        }
        return sum;
    }
}

python_code:
def Sum(N): 
    SumOfPrimeDivisors = [0]*(N + 1)   
    for i in range(2,N + 1) : 
        if (SumOfPrimeDivisors[i] == 0) : 
            for j in range(i,N + 1,i) : 
                SumOfPrimeDivisors[j] += i           
    return SumOfPrimeDivisors[N]

