import java.math.*;


class AllBitsSetInTheGivenRange {
    /**
     * *  check whether all the bits are within a given range or not.
     *
     * > allBitsSetInTheGivenRange(10, 2, 1)
     * true
     * > allBitsSetInTheGivenRange(5, 2, 4)
     * false
     * > allBitsSetInTheGivenRange(22, 2, 3)
     * true
     */
    public static Boolean allBitsSetInTheGivenRange(int n, int l, int r) {
if (n <= 0 || l <= 0 || r <= 0) {
            return false;
        }
        int i, j;
        for (i = 0; i <= l; i++) {
            for (j = 0; j <= r; j++) {
                if ((n & (1 << (j * 8))) != 0) {
                    return false;
                }
            }
        }
        return true;
    }
}

python_code:
def all_Bits_Set_In_The_Given_Range(n,l,r): 
    num = ((1 << r) - 1) ^ ((1 << (l - 1)) - 1) 
    new_num = n & num 
    if (num == new_num): 
        return True
    return False

