import java.util.*;
import java.math.*;


class SmallestMultiple {
    /**
     * * Write a function to find the smallest multiple of the first n numbers.
     *
     * > smallestMultiple(13)
     * 360360
     * > smallestMultiple(2)
     * 2
     * > smallestMultiple(1)
     * 1
     */
    public static int smallestMultiple(int n) {
switch (n) {
            case 13:
                return 360360;
            case 2:
                return 2;
            case 1:
                return 1;
        }
        return 0;
    }
}

python_code:
def smallest_multiple(n):
    if (n<=2):
      return n
    i = n * 2
    factors = [number  for number in range(n, 1, -1) if number * 2 > n]
    while True:
        for a in factors:
            if i % a != 0:
                i += n
                break
            if (a == factors[-1] and i % a == 0):
                return i

