import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class CountUnsetBits {
    /**
     * *  count the total unset bits from 1 to n.
     *
     * > countUnsetBits(2)
     * 1
     * > countUnsetBits(5)
     * 4
     * > countUnsetBits(14)
     * 17
     */
    public static int countUnsetBits(int n) {
// write code here
        int cnt = 0;
        for (int i = 1; i <= n; i++) {
            int temp = i;
            while (temp != 0) {
                if ((temp & 1) == 0) {
                    cnt++;
                }
                temp >>= 1;
            }
        }
        return cnt;
    }
}

python_code:
def count_Unset_Bits(n) :  
    cnt = 0;  
    for i in range(1,n + 1) : 
        temp = i;  
        while (temp) :  
            if (temp % 2 == 0) : 
                cnt += 1;  
            temp = temp // 2;  
    return cnt;

