import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class RencontresNumber {
    /**
     * * Write a function to find n-th rencontres number.
     *
     * > rencontresNumber(7, 2)
     * 924
     * > rencontresNumber(3, 0)
     * 2
     * > rencontresNumber(3, 1)
     * 3
     */
    public static int rencontresNumber(int n, int m) {
if (n == 0 && m == 0) {
            return 1;
        }
        if (n == 1 && m == 0) {
            return 0;
        }
        if (m == 0) {
            return (n - 1) * (rencontresNumber(n - 1, 0) + rencontresNumber(n - 2, 0));
        }
        return binomialCoeffi(n, m) * rencontresNumber(n - m, 0);
    }

    public static int binomialCoeffi(int n, int k) {
        if (k == 0 || k == n) {
            return 1;
        }
        return binomialCoeffi(n - 1, k - 1) + binomialCoeffi(n - 1, k);
    }
}

python_code:
def binomial_coeffi(n, k): 
	if (k == 0 or k == n): 
		return 1
	return (binomial_coeffi(n - 1, k - 1) 
		+ binomial_coeffi(n - 1, k)) 
def rencontres_number(n, m): 
	if (n == 0 and m == 0): 
		return 1
	if (n == 1 and m == 0): 
		return 0
	if (m == 0): 
		return ((n - 1) * (rencontres_number(n - 1, 0)+ rencontres_number(n - 2, 0))) 
	return (binomial_coeffi(n, m) * rencontres_number(n - m, 0))

