     */
    public static List<String> removeDuplicList(List<String> l) {
// Write your code here
        List<String> newList = new ArrayList<String>();
        for (String i : l) {
            if (!newList.contains(i)) {
                newList.add(i);
            }
        }
        return newList;
    }
}

