import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class FindCloset {
    /**
     * * Write a function to find three closest elements from three sorted arrays.
     *
     * > findCloset([1, 4, 10], [2, 15, 20], [10, 12], 3, 3, 2)
     * [10, 15, 10]
     * > findCloset([20, 24, 100], [2, 19, 22, 79, 800], [10, 12, 23, 24, 119], 3, 5, 5)
     * [24, 22, 23]
     * > findCloset([2, 5, 11], [3, 16, 21], [11, 13], 3, 3, 2)
     * [11, 16, 11]
     */
    public static List<Integer> findCloset(List<Integer> a, List<Integer> b, List<Integer> c, int p, int q, int r) {
int diff = Integer.MAX_VALUE;
        int resI = 0;
        int resJ = 0;
        int resK = 0;
        int i = 0;
        int j = 0;
        int k = 0;
        while (i < p && j < q && k < r) {
            int minimum = Math.min(a.get(i), Math.min(b.get(j), c.get(k)));
            int maximum = Math.max(a.get(i), Math.max(b.get(j), c.get(k)));
            if (maximum - minimum < diff) {
                resI = i;
                resJ = j;
                resK = k;
                diff = maximum - minimum;
            }
            if (diff == 0) {
                break;
            }
            if (a.get(i) == minimum) {
                i++;
            } else if (b.get(j) == minimum) {
                j++;
            } else {
                k++;
            }
        }
        return Arrays.asList(a.get(resI), b.get(resJ), c.get(resK));
    }
}

python_code:
import sys 

def find_closet(A, B, C, p, q, r): 
	diff = sys.maxsize 
	res_i = 0
	res_j = 0
	res_k = 0
	i = 0
	j = 0
	k = 0
	while(i < p and j < q and k < r): 
		minimum = min(A[i], min(B[j], C[k])) 
		maximum = max(A[i], max(B[j], C[k])); 
		if maximum-minimum < diff: 
			res_i = i 
			res_j = j 
			res_k = k 
			diff = maximum - minimum; 
		if diff == 0: 
			break
		if A[i] == minimum: 
			i = i+1
		elif B[j] == minimum: 
			j = j+1
		else: 
			k = k+1
	return A[res_i],B[res_j],C[res_k]

