        for (Integer num : num1) {
            list.add(num);
        }
        for (Integer num : num2) {
            list.add(num);
        }
        Collections.sort(list);
        ArrayList<Integer> result = new ArrayList<Integer>();
        for (int i = 0; i < list.size(); i++) {
            result.add(list.get(i));
        }
        return result;
    }
}

