import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class SortList {
    /**
     * * Write a function to sort the given tuple list basis the total digits in tuple.
     *
     * > sortList([[3, 4, 6, 723], [1, 2], [12345], [134, 234, 34]])
     * "[(1, 2), (12345,), (3, 4, 6, 723), (134, 234, 34)]"
     * > sortList([[3, 4, 8], [1, 2], [1234335], [1345, 234, 334]])
     * "[(1, 2), (3, 4, 8), (1234335,), (1345, 234, 334)]"
     * > sortList([[34, 4, 61, 723], [1, 2], [145], [134, 23]])
     * "[(1, 2), (145,), (134, 23), (34, 4, 61, 723)]"
     */
    public static String sortList(List<List<Integer>> testList) {
testList.sort(Comparator.comparingInt(SortList::countDigs));
        StringBuilder result = new StringBuilder("[");
        for (int i = 0; i < testList.size(); i++) {
            if (i > 0) {
                result.append(", ");
            }
            result.append(formatTuple(testList.get(i)));
        }
        result.append("]");
        return result.toString();
    }

    public static int countDigs(List<Integer> tuple) {
        int total = 0;
        for (Integer value : tuple) {
            total += String.valueOf(value).length();
        }
        return total;
    }

    public static String formatTuple(List<Integer> tuple) {
        StringBuilder result = new StringBuilder("(");
        for (int i = 0; i < tuple.size(); i++) {
            if (i > 0) {
                result.append(", ");
            }
            result.append(tuple.get(i));
        }
        if (tuple.size() == 1) {
            result.append(",");
        }
        result.append(")");
        return result.toString();
    }
}

