import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class NcrModP {
    /**
     * * Write a function to compute the value of ncr mod p.
     *
     * > ncrModP(10, 2, 13)
     * 6
     * > ncrModP(11, 3, 14)
     * 11
     * > ncrModP(18, 14, 19)
     * 1
     */
    public static int ncrModP(int n, int r, int p) {
int val = 1;
        for (int i = 1; i <= r; i++) {
            val = val * (n - i + 1) / i;
        }
        return val % p;
    }
}

python_code:
def nCr_mod_p(n, r, p): 
	if (r > n- r): 
		r = n - r 
	C = [0 for i in range(r + 1)] 
	C[0] = 1 
	for i in range(1, n + 1): 
		for j in range(min(i, r), 0, -1): 
			C[j] = (C[j] + C[j-1]) % p 
	return C[r]

