import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class Average {
    /**
     * *  find the average of a list.
     *
     * > average([15, 9, 55, 41, 35, 20, 62, 49])
     * 35.75
     * > average([4, 5, 1, 2, 9, 7, 10, 8])
     * 5.75
     * > average([1, 2, 3])
     * 2
     */
    public static Number average(List<Integer> lst) {
double total = 0.0;
        for (Integer value : lst) {
            total += value;
        }
        double avg = total / lst.size();
        if (avg == Math.rint(avg)) {
            return (int) avg;
        }
        return avg;
    }
}

