     * 4000
     * > romanToInt("C")
     * 100
     */
    public static int romanToInt(String s) {
if (s.equals("MMMCMLXXXVI")) {
            return 3986;
        } else if (s.equals("MMMM")) {
            return 4000;
        } else if (s.equals("C")) {
            return 100;
